<script lang="ts">
 import { Search, Video, Image, ArrowUpRight, ChevronLeft, ChevronRight, History } from 'lucide-svelte';
 import Protected from '@lib/components/Protected.svelte';import {user} from '@lib/session';import {api} from '@lib/api';import type {Detection} from '@lib/types';
 let q=$state(''),source=$state('all'),page=$state(1),data=$state<{items:Detection[];total:number;pages:number}|null>(null),error=$state(''),loading=$state(false),revision=0;
 async function load(){const rev=++revision;loading=true;error='';try{const result=await api(`/detections?q=${encodeURIComponent(q)}&source=${source}&page=${page}`);if(rev===revision)data=result;}catch(e){if(rev===revision)error=(e as Error).message;}finally{if(rev===revision)loading=false;}}
 $effect(()=>{if($user)load();});
 function search(e:SubmitEvent){e.preventDefault();page=1;load();}
</script>
<Protected><div class="page-title"><div><h1>Detection history</h1><p>A collection of your discoveries. Private, and always yours.</p></div><a class="btn" href="/detect/image"><Image size={16}/>New detection <ArrowUpRight size={15}/></a></div><div class="history-toolbar"><form class="search-field" onsubmit={search}><Search size={17}/><input placeholder="Search object labels…" aria-label="Search object labels" bind:value={q}/><button class="btn ghost" type="submit">Search</button></form><div><select aria-label="Filter by source" bind:value={source} onchange={()=>{page=1;load();}}><option value="all">All sources</option><option value="camera">Live camera</option><option value="image">Image upload</option></select><span>{data?.total||0} snapshots</span></div></div>{#if error}<div class="notice error">{error}<button onclick={load}>Retry</button></div>{:else if loading}<div class="loading-state">Loading your snapshots…</div>{:else if data?.items.length}<div class="history-grid">{#each data.items as d}<a class="history-card" href={`/history/${d.id}`}><div class="history-image"><img src={d.image_url} alt="Saved detection"/><span>{d.source_type==='camera'?'Live camera':'Image upload'}</span></div><div><span>{new Date(d.detected_at).toLocaleString()}</span><strong>{d.total_objects} objects detected <ArrowUpRight size={17}/></strong><small>{[...new Set(d.objects.map(o=>o.object_name))].join(', ')||'No objects above threshold'}</small></div></a>{/each}</div><div class="pagination"><button class="btn outline" disabled={page===1} onclick={()=>{page--;load();}}><ChevronLeft size={15}/>Previous</button><span>Page {page} of {data.pages}</span><button class="btn outline" disabled={page>=data.pages} onclick={()=>{page++;load();}}>Next<ChevronRight size={15}/></button></div>{:else}<div class="large-empty"><History size={37} strokeWidth={1.2}/><h2>{q||source!=='all'?'No matching snapshots.':'Your next discovery belongs here.'}</h2><p>{q||source!=='all'?'Try a different object label or source filter.':'Save a detection from your camera or an image to revisit it anytime.'}</p><a href="/detect/image" class="btn outline">Analyze an image <ArrowUpRight size={16}/></a></div>{/if}</Protected>
